-- The text and style of every character run in pandoc inlines (or a string), as xe.inl writes them: emphasis
-- italic, strong bold, quotes curly, a space as a space; M.prep (when the filter sets it) first applies to every
-- list of inlines the rules xe.inl applies (xe.unabbrev, xe.bind_signs).
function M.runs(x, o, out)
  o, out = o or {}, out or {}
  if x == nil then return out end
  if type(x) == "string" then
    out[#out + 1] = { t = x, b = o.b, i = o.i }
    return out
  end
  if M.prep then x = M.prep(x) end
  for _, el in ipairs(x) do
    local t = el.t
    if t == "Str" then
      out[#out + 1] = { t = el.text, b = o.b, i = o.i }
    elseif t == "Space" or t == "SoftBreak" or t == "LineBreak" then
      out[#out + 1] = { t = " ", b = o.b, i = o.i }
    elseif t == "Emph" then
      M.runs(el.content, { b = o.b, i = true }, out)
    elseif t == "Strong" then
      M.runs(el.content, { b = true, i = o.i }, out)
    elseif t == "Quoted" then
      local q = el.quotetype == "DoubleQuote" and { "\u{201C}", "\u{201D}" } or { "\u{2018}", "\u{2019}" }
      out[#out + 1] = { t = q[1], b = o.b, i = o.i }
      M.runs(el.content, o, out)
      out[#out + 1] = { t = q[2], b = o.b, i = o.i }
    elseif el.content then
      M.runs(el.content, o, out)
    else
      out[#out + 1] = { t = pandoc.utils.stringify(el), b = o.b, i = o.i }
    end
  end
  return out
end

local BREAK_AFTER = { [" "] = true, ["\u{2013}"] = true, ["\u{2014}"] = true, ["\u{200B}"] = true }

-- The number of lines `runs` (M.runs) wrap to in a measure of `width` twips at `size` half points; `first` twips of
-- the first line are taken by an indent or a label (0 when not given), `hang` twips of every later line.
function M.count(runs, width, size, first, hang)
  local scale = size / 2 / 1000 * 20      -- twips per 1/1000 em
  local chars = {}
  for _, r in ipairs(runs) do
    local tab = M.W[(r.b and "b" or "") .. (r.i and "i" or "")] or M.W.r
    for _, c in utf8.codes(r.t) do
      local ch = utf8.char(c)
      chars[#chars + 1] = { c = ch, w = (tab[ch] or M.W.r[ch] or 500) * scale }
    end
  end
  -- segments: up to and including a break opportunity; `tail` is the width of trailing spaces
  local segs, cur, tail = {}, 0, 0
  for k, ch in ipairs(chars) do
    if ch.c == " " then tail = tail + ch.w else cur = cur + tail + ch.w; tail = 0 end
    local nxt = chars[k + 1]
    local brk = (BREAK_AFTER[ch.c] and not (nxt and nxt.c == " "))
      or (ch.c == "-" and nxt and not nxt.c:match("%d") and nxt.c ~= " ")
      or (nxt and (nxt.c == "\u{2014}") and ch.c ~= " ")
    if brk then
      segs[#segs + 1] = { w = cur, tail = tail }
      cur, tail = 0, 0
    end
  end
  if cur > 0 or tail > 0 then segs[#segs + 1] = { w = cur, tail = tail } end
  local lines, used, avail = 1, 0, width - (first or 0)
  for _, s in ipairs(segs) do
    if used > 0 and used + s.w > avail + 0.01 then
      lines = lines + 1
      avail = width - (hang or 0)
      used = s.w + s.tail
    else
      used = used + s.w + s.tail
    end
  end
  return lines
end

return M
